import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { Pool } from "pg";
import { schema } from "./db.js";

/** Folder holding the SQL generated by `drizzle-kit generate`. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../drizzle", import.meta.url));

function open(url: string, max: number) {
  return drizzle(new Pool({ connectionString: url, max }), { schema });
}

/** A pooled node-postgres connection over the ledger schema. */
export type LedgerDatabase = ReturnType<typeof open>;

/**
 * Open a pooled connection over the ledger schema.
 *
 * The package never reads the environment: the caller passes the URL, so the
 * gateway owns the pool and the tests can use PGlite instead.
 *
 * @param url - Postgres connection string.
 * @param max - Maximum pooled connections.
 * @returns A Drizzle connection, with the pool on `$client`.
 */
export function createLedgerDatabase(url: string, max = 10): LedgerDatabase {
  if (!url) throw new Error("ledger: a Postgres connection string is required");
  return open(url, max);
}

/**
 * Apply the generated migrations.
 *
 * @param db - Connection returned by `createLedgerDatabase`.
 */
export async function runMigrations(db: LedgerDatabase): Promise<void> {
  await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
}
